CREATE DATABASE IF NOT EXISTS network_management;
USE network_management;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS devices (id INT AUTO_INCREMENT PRIMARY KEY,device_name VARCHAR(100) NOT NULL,device_type VARCHAR(50) NOT NULL,ip_address VARCHAR(45) UNIQUE NOT NULL,location VARCHAR(150),description TEXT,status VARCHAR(20) DEFAULT 'UNKNOWN',last_checked DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS monitoring_logs (id INT AUTO_INCREMENT PRIMARY KEY,device_id INT NOT NULL,status VARCHAR(20) NOT NULL,response_time FLOAT DEFAULT 0,packet_loss FLOAT DEFAULT 0,checked_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS alerts (id INT AUTO_INCREMENT PRIMARY KEY,device_id INT NOT NULL,alert_type VARCHAR(50) NOT NULL,severity VARCHAR(20) NOT NULL,message TEXT NOT NULL,is_resolved BOOLEAN DEFAULT FALSE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,resolved_at DATETIME NULL,FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS network_metrics (id INT AUTO_INCREMENT PRIMARY KEY,device_id INT NOT NULL,cpu_usage FLOAT DEFAULT 0,memory_usage FLOAT DEFAULT 0,bandwidth_usage FLOAT DEFAULT 0,latency FLOAT DEFAULT 0,recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
